  String get datingHowItWorksSubscriptionsDesc => _t({'fr': '• Gratuit : swipes limités par jour.\n• Plus : plus de swipes, plus de likes et accès à plus de profils.\n• Gold : swipes illimités, voir qui vous a liké, boost gratuit quotidien et messages directs.', 'en': '• Free: limited swipes per day.\n• Plus: more swipes, more likes and access to more profiles.\n• Gold: unlimited swipes, see who liked you, free daily boost and direct messages.', 'es': '• Gratis: deslizamientos limitados por día.\n• Plus: más deslizamientos, más me gusta y acceso a más perfiles.\n• Gold: deslizamientos ilimitados, ver quién te dio me gusta, impulso diario gratis y mensajes directos.', 'de': '• Kostenlos: begrenzte Swipes pro Tag.\n• Plus: mehr Swipes, mehr Likes und Zugang zu mehr Profilen.\n• Gold: unbegrenzte Swipes, sehen, wer dich gelikt hat, täglicher kostenloser Boost und Direktnachrichten.', 'ar': '• مجاني: عدد محدود من التمريرات يوميًا.\n• Plus: مزيد من التمريرات والإعجابات والوصول إلى مزيد من الملفات الشخصية.\n• Gold: تمريرات غير محدودة، رؤية من أعجب بك، تعزيز يومي مجاني ورسائل مباشرة.', 'pt': '• Gratuito: deslizamentos limitados por dia.\n• Plus: mais deslizamentos, mais curtidas e acesso a mais perfis.\n• Gold: deslizamentos ilimitados, veja quem curtiu você, boost diário gratuito e mensagens diretas.', 'zh': '• 免费版：每日滑动次数有限。\n• Plus：更多滑动、更多喜欢，并可查看更多资料。\n• Gold：无限滑动、查看谁喜欢了你、每日免费推广和直接私信。', 'sw': '• Bure: kusogeza kwa idadi ndogo kwa siku.\n• Plus: kusogeza zaidi, like zaidi na ufikiaji wa wasifu zaidi.\n• Gold: kusogeza bila kikomo, kuona aliyekupenda, ongezeko la bure la kila siku na ujumbe wa moja kwa moja.'});
  String get datingHowItWorksBoostTitle => _t({'fr': 'Booster son profil', 'en': 'Boosting your profile', 'es': 'Impulsar tu perfil', 'de': 'Profil boosten', 'ar': 'تعزيز ملفك الشخصي', 'pt': 'Impulsionar seu perfil', 'zh': '推广您的资料', 'sw': 'Kuongeza wasifu wako'});
  String get datingHowItWorksBoostDesc => _t({'fr': 'Activez un boost pour mettre votre profil plus en avant dans le fil de découverte et obtenir le badge "⚡ Boosté", de 1 jour à 6 mois.', 'en': 'Activate a boost to feature your profile more prominently in the discovery feed and get the "⚡ Boosted" badge, from 1 day up to 6 months.', 'es': 'Activa un impulso para destacar tu perfil en el feed de descubrimiento y obtener la insignia "⚡ Impulsado", de 1 día a 6 meses.', 'de': 'Aktiviere einen Boost, um dein Profil im Entdecken-Feed prominenter zu platzieren und das Abzeichen "⚡ Geboostet" zu erhalten, von 1 Tag bis 6 Monate.', 'ar': 'فعّل التعزيز لإبراز ملفك الشخصي في قائمة الاستكشاف والحصول على شعار "⚡ معزز"، من يوم واحد إلى 6 أشهر.', 'pt': 'Ative um boost para destacar seu perfil no feed de descoberta e ganhar o selo "⚡ Impulsionado", de 1 dia a 6 meses.', 'zh': '开启推广功能，让您的资料在发现页面中更显眼，并获得"⚡ 已推广"标志，时长从1天到6个月。', 'sw': 'Wezesha ongezeko ili wasifu wako uonekane zaidi kwenye mlisho wa ugunduzi na kupata alama ya "⚡ Imeongezwa", kuanzia siku 1 hadi miezi 6.'});
  String get datingHowItWorksGotIt => _t({'fr': 'Compris, c\'est parti !', 'en': 'Got it, let\'s go!', 'es': '¡Entendido, vamos!', 'de': 'Verstanden, los geht\'s!', 'ar': 'فهمت، هيا بنا!', 'pt': 'Entendi, vamos lá!', 'zh': '知道了，开始吧！', 'sw': 'Nimepata, twende!'});
  String get datingBoostedBadge => _t({'fr': '⚡ Boosté', 'en': '⚡ Boosted', 'es': '⚡ Impulsado', 'de': '⚡ Geboostet', 'ar': '⚡ معزز', 'pt': '⚡ Impulsionado', 'zh': '⚡ 已推广', 'sw': '⚡ Imeongezwa'});

  String get datingExpandedSearchCriteria => _t({'fr': 'Aucun nouveau profil ne correspond à vos critères : nous avons élargi votre recherche pour vous montrer plus de profils.', 'en': 'No new profiles match your criteria: we expanded your search to show you more profiles.', 'es': 'Ningún perfil nuevo coincide con tus criterios: hemos ampliado tu búsqueda para mostrarte más perfiles.', 'de': 'Keine neuen Profile entsprechen deinen Kriterien: Wir haben deine Suche erweitert, um dir mehr Profile zu zeigen.', 'ar': 'لا توجد ملفات جديدة تطابق معاييرك: لقد وسّعنا بحثك لعرض المزيد من الملفات الشخصية.', 'pt': 'Nenhum perfil novo corresponde aos seus critérios: ampliámos a sua pesquisa para mostrar mais perfis.', 'zh': '没有符合您条件的新资料：我们已扩大搜索范围，为您展示更多资料。', 'sw': 'Hakuna wasifu mpya unaolingana na vigezo vyako: tumepanua utafutaji wako kuonyesha wasifu zaidi.'});

