  String get datingVerifiedOnlyGoldOnly => _t({'fr': 'Le filtre "profils vérifiés" est réservé à l\'abonnement Gold.', 'en': 'The "verified profiles" filter is reserved for Gold subscribers.', 'es': 'El filtro "perfiles verificados" está reservado para suscriptores Gold.', 'de': 'Der Filter "Verifizierte Profile" ist Gold-Abonnenten vorbehalten.', 'ar': 'فلتر "الملفات الموثقة" مخصص لمشتركي Gold فقط.', 'pt': 'O filtro "perfis verificados" é exclusivo para assinantes Gold.', 'zh': '"已验证资料"筛选仅限Gold订阅用户。', 'sw': 'Kichujio cha "wasifu zilizothibitishwa" ni kwa wanaojiunga na Gold tu.'});

