  String get datingVerificationPending => _t({'fr': 'Vérification en attente', 'en': 'Verification pending', 'es': 'Verificación pendiente', 'de': 'Verifizierung ausstehend', 'ar': 'التحقق قيد الانتظار', 'pt': 'Verificação pendente', 'zh': '验证审核中', 'sw': 'Uthibitishaji unasubiri'});
