  String get datingVerificationRequestSent => _t({'fr': 'Demande de vérification envoyée ! Contactez le service client pour finaliser.', 'en': 'Verification request sent! Please contact customer support to finalize.', 'es': '¡Solicitud de verificación enviada! Contacta al servicio al cliente para finalizar.', 'de': 'Verifizierungsanfrage gesendet! Bitte kontaktiere den Kundenservice, um den Vorgang abzuschließen.', 'ar': 'تم إرسال طلب التحقق! يرجى الاتصال بخدمة العملاء لإتمام العملية.', 'pt': 'Solicitação de verificação enviada! Contate o atendimento ao cliente para finalizar.', 'zh': '验证申请已发送！请联系客服以完成。', 'sw': 'Ombi la uthibitishaji limetumwa! Tafadhali wasiliana na huduma kwa wateja ili kukamilisha.'});
