  String get datingVerifyProfileGoldOnly => _t({'fr': 'La demande de vérification de profil est réservée à l\'abonnement Gold.', 'en': 'Profile verification requests are reserved for Gold subscribers.', 'es': 'Las solicitudes de verificación de perfil están reservadas para suscriptores Gold.', 'de': 'Profilverifizierungsanfragen sind Gold-Abonnenten vorbehalten.', 'ar': 'طلبات توثيق الملف الشخصي مخصصة لمشتركي Gold فقط.', 'pt': 'As solicitações de verificação de perfil são exclusivas para assinantes Gold.', 'zh': '资料验证申请仅限Gold订阅用户。', 'sw': 'Maombi ya uthibitishaji wa wasifu ni kwa wanaojiunga na Gold tu.'});
