  String get datingDirectMessageDescription => _t({'fr': 'Envoyez un message directement à cette personne sans attendre un match (1 par jour, réservé Gold).', 'en': 'Send a message directly to this person without waiting for a match (1 per day, Gold only).', 'es': 'Envía un mensaje directamente a esta persona sin esperar un match (1 por día, solo Gold).', 'de': 'Sende dieser Person direkt eine Nachricht, ohne auf ein Match zu warten (1 pro Tag, nur Gold).', 'ar': 'أرسل رسالة مباشرة لهذا الشخص دون انتظار تطابق (1 يوميًا، Gold فقط).', 'pt': 'Envie uma mensagem diretamente para esta pessoa sem esperar um match (1 por dia, exclusivo Gold).', 'zh': '无需等待配对即可直接给此人发消息（每天1次，仅限Gold）。', 'sw': 'Tuma ujumbe moja kwa moja kwa mtu huyu bila kusubiri mechi (1 kwa siku, Gold tu).'});
